17 if($inputMark >= 80) $gradeChar = "A";
18 else if($inputMark >= 70) $gradeChar = "B";
19 else if($inputMark >= 60) $gradeChar = "C";
20 else if($inputMark >= 50) $gradeChar = "D";
21 else if($inputMark >= 40) $gradeChar = "E";
